import React, { useEffect, useMemo, useState } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";
import "../style/customers.css";

export default function Customers() {
  const [customers, setCustomers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState("");
  const [error, setError] = useState("");

  const navigate = useNavigate();

  // ============================
  // CURRENT USER
  // ============================
  const user = JSON.parse(localStorage.getItem("user") || "null");

  const isAdmin =
    user?.role?.toLowerCase() === "admin";

  // ============================
  // GET CUSTOMERS
  // ============================
  const getCustomers = async () => {
    try {
      setLoading(true);
      setError("");

      const token = localStorage.getItem("token");

      const res = await axios.get(
        "http://localhost:5000/api/v1/customers",
        {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        }
      );

      setCustomers(res.data || []);
    } catch (error) {
      console.error("Failed to fetch customers:", error);
      setError("Unable to load customers. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    getCustomers();
  }, []);

  // ============================
  // DELETE CUSTOMER
  // ============================
  const deleteCustomer = async (id) => {
    const confirmDelete = window.confirm(
      "Are you sure you want to delete this customer?"
    );

    if (!confirmDelete) return;

    try {
      const token = localStorage.getItem("token");

      await axios.delete(
        `http://localhost:5000/api/v1/customers/${id}`,
        {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        }
      );

      setCustomers((prev) =>
        prev.filter((customer) => customer.id !== id)
      );
    } catch (error) {
      console.error("Delete failed:", error);
      alert("Unable to delete customer.");
    }
  };

  // ============================
  // EDIT CUSTOMER
  // ============================
  const editCustomer = (id) => {
    navigate(`/editcustomer/${id}`);
  };

  // ============================
  // STATISTICS
  // ============================
  const totalCustomers = customers.length;

  const totalAdmins = customers.filter(
    (customer) =>
      customer.role?.toLowerCase() === "admin"
  ).length;

  const totalUsers = customers.filter(
    (customer) =>
      customer.role?.toLowerCase() === "user"
  ).length;

  // ============================
  // SEARCH
  // ============================
  const filteredCustomers = useMemo(() => {
    const value = search.trim().toLowerCase();

    if (!value) return customers;

    return customers.filter((customer) => {
      return (
        String(customer.id)
          .toLowerCase()
          .includes(value) ||
        customer.name
          ?.toLowerCase()
          .includes(value) ||
        customer.email
          ?.toLowerCase()
          .includes(value) ||
        customer.phone
          ?.toLowerCase()
          .includes(value) ||
        customer.city
          ?.toLowerCase()
          .includes(value) ||
        customer.role
          ?.toLowerCase()
          .includes(value)
      );
    });
  }, [customers, search]);

  // ============================
  // GET INITIAL
  // ============================
  const getInitial = (name) => {
    return name?.charAt(0)?.toUpperCase() || "?";
  };

  return (
    <div className="customers-page">

      <div className="container-fluid px-3 px-md-4">

        {/* ============================
            HEADER
        ============================ */}
        <div className="customers-header">

          <div className="header-left">

            <div className="header-icon">
              👥
            </div>

            <div>
              <h1>Customers</h1>

              <p>
                Manage and monitor your customers
                from one place.
              </p>
            </div>

          </div>

          {isAdmin && (
            <button
              className="add-customer-btn"
              onClick={() => navigate("/addcustomer")}
            >
              <span>+</span>
              Add Customer
            </button>
          )}

        </div>

        {/* ============================
            STATISTICS
        ============================ */}
        <div className="stats-grid">

          {/* Total */}
          <div className="stat-card total-card">
            <div>
              <span className="stat-label">
                Total Customers
              </span>

              <h2>{totalCustomers}</h2>

              <small>
                All registered customers
              </small>
            </div>

            <div className="stat-icon">
              👥
            </div>
          </div>

          {/* Admin */}
          <div className="stat-card admin-card">
            <div>
              <span className="stat-label">
                Administrators
              </span>

              <h2>{totalAdmins}</h2>

              <small>
                Admin accounts
              </small>
            </div>

            <div className="stat-icon">
              🛡️
            </div>
          </div>

          {/* Users */}
          <div className="stat-card user-card">
            <div>
              <span className="stat-label">
                Normal Users
              </span>

              <h2>{totalUsers}</h2>

              <small>
                Registered users
              </small>
            </div>

            <div className="stat-icon">
              👤
            </div>
          </div>

        </div>

        {/* ============================
            CUSTOMER TABLE SECTION
        ============================ */}
        <div className="customer-section">

          {/* Table Header */}
          <div className="customer-section-header">

            <div>
              <h3>Customer List</h3>

              <p>
                View and manage registered customers.
              </p>
            </div>

            <div className="customer-count">
              {filteredCustomers.length}
              <span> / {customers.length}</span>
            </div>

          </div>

          {/* ============================
              SEARCH BAR
          ============================ */}
          <div className="customer-toolbar">

            <div className="search-box">

              <span className="search-icon">
                🔍
              </span>

              <input
                type="text"
                placeholder="Search by name, email, phone, city..."
                value={search}
                onChange={(e) =>
                  setSearch(e.target.value)
                }
              />

              {search && (
                <button
                  className="clear-search"
                  onClick={() => setSearch("")}
                  title="Clear search"
                >
                  ×
                </button>
              )}

            </div>

            {search && (
              <span className="search-result">
                {filteredCustomers.length} result
                {filteredCustomers.length !== 1
                  ? "s"
                  : ""}{" "}
                found
              </span>
            )}

          </div>

          {/* ============================
              LOADING
          ============================ */}
          {loading ? (

            <div className="state-container">

              <div className="custom-spinner"></div>

              <h4>Loading customers...</h4>

              <p>
                Please wait while we fetch customer data.
              </p>

            </div>

          ) : error ? (

            /* ============================
                ERROR
            ============================ */
            <div className="state-container">

              <div className="state-icon error-icon">
                ⚠️
              </div>

              <h4>Something went wrong</h4>

              <p>{error}</p>

              <button
                className="retry-btn"
                onClick={getCustomers}
              >
                Try Again
              </button>

            </div>

          ) : filteredCustomers.length === 0 ? (

            /* ============================
                EMPTY / NO SEARCH RESULT
            ============================ */
            <div className="state-container">

              <div className="state-icon">
                {search ? "🔍" : "👥"}
              </div>

              <h4>
                {search
                  ? "No Customers Found"
                  : "No Customers Yet"}
              </h4>

              <p>
                {search
                  ? `No customers match "${search}".`
                  : "There are no customers in your database yet."}
              </p>

              {search ? (
                <button
                  className="retry-btn"
                  onClick={() => setSearch("")}
                >
                  Clear Search
                </button>
              ) : (
                isAdmin && (
                  <button
                    className="add-first-btn"
                    onClick={() =>
                      navigate("/addcustomer")
                    }
                  >
                    + Add First Customer
                  </button>
                )
              )}

            </div>

          ) : (

            /* ============================
                TABLE
            ============================ */
            <div className="table-wrapper">

              <table className="customers-table">

                <thead>
                  <tr>
                    <th>ID</th>
                    <th>Customer</th>
                    <th>Email</th>
                    <th>Phone</th>
                    <th>City</th>
                    <th>Role</th>
                    <th className="action-column">
                      Actions
                    </th>
                  </tr>
                </thead>

                <tbody>

                  {filteredCustomers.map((customer) => {

                    const role =
                      customer.role?.toLowerCase();

                    const isCustomerAdmin =
                      role === "admin";

                    return (
                      <tr key={customer.id}>

                        {/* ID */}
                        <td>
                          <span className="customer-id">
                            #{customer.id}
                          </span>
                        </td>

                        {/* CUSTOMER */}
                        <td>
                          <div className="customer-info">

                            <div className="customer-avatar">
                              {getInitial(
                                customer.name
                              )}
                            </div>

                            <div>
                              <strong>
                                {customer.name ||
                                  "Unknown"}
                              </strong>

                              <small>
                                Customer #{customer.id}
                              </small>
                            </div>

                          </div>
                        </td>

                        {/* EMAIL */}
                        <td>
                          <span className="email-text">
                            {customer.email ||
                              "N/A"}
                          </span>
                        </td>

                        {/* PHONE */}
                        <td>
                          {customer.phone ? (
                            <span className="phone-text">
                              {customer.phone}
                            </span>
                          ) : (
                            <span className="not-available">
                              N/A
                            </span>
                          )}
                        </td>

                        {/* CITY */}
                        <td>
                          <span className="city-badge">
                            📍{" "}
                            {customer.city ||
                              "N/A"}
                          </span>
                        </td>

                        {/* ROLE */}
                        <td>
                          {isCustomerAdmin ? (
                            <span className="role-badge admin-role">
                              🛡️ Admin
                            </span>
                          ) : (
                            <span className="role-badge user-role">
                              👤 User
                            </span>
                          )}
                        </td>

                        {/* ACTIONS */}
                        <td className="action-column">

                          {isAdmin ? (

                            <div className="action-buttons">

                              <button
                                className="edit-btn"
                                onClick={() =>
                                  editCustomer(
                                    customer.id
                                  )
                                }
                                title="Edit customer"
                              >
                                ✏️
                              </button>

                              <button
                                className="delete-btn"
                                onClick={() =>
                                  deleteCustomer(
                                    customer.id
                                  )
                                }
                                title="Delete customer"
                              >
                                🗑️
                              </button>

                            </div>

                          ) : (

                            <span className="view-only">
                              View Only
                            </span>

                          )}

                        </td>

                      </tr>
                    );
                  })}

                </tbody>

              </table>

            </div>

          )}

        </div>

      </div>
    </div>
  );
}
